<?php
require_once __DIR__.'/auth.php';
if (admin_logged_in()) { header('Location: index.php'); exit; }
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { try { $u=trim($_POST['username']??''); $p=$_POST['password']??''; $st=db()->prepare('SELECT * FROM admins WHERE username=? LIMIT 1'); $st->execute([$u]); $a=$st->fetch(); if($a && password_verify($p,$a['password_hash'])) { session_regenerate_id(true); $_SESSION['admin_id']=$a['id']; $_SESSION['admin_username']=$a['username']; header('Location: index.php'); exit; } $error='Invalid username or password. If this is a fresh installation, open reset_admin.php once.'; } catch (Throwable $e) { $error='Database error: '.$e->getMessage(); } }
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><style>body{font-family:Arial;background:#f4efe7;display:grid;place-items:center;min-height:100vh}.box{width:min(420px,90%);background:#fff;padding:30px;border-radius:10px}input{width:100%;padding:12px;margin:8px 0 16px;box-sizing:border-box}button{width:100%;padding:12px;background:#7d402d;color:#fff;border:0;border-radius:5px}.err{color:#a22;margin-bottom:12px}</style></head><body><div class="box"><h1>Admin Login</h1><?php if($error):?><div class="err"><?php echo htmlspecialchars($error);?></div><?php endif;?><form method="post"><label>Username</label><input name="username" required><label>Password</label><input name="password" type="password" required><button>Login</button></form><p><a href="../index.php">← Back to website</a></p></div></body></html>
